test('applyVoucher: applies voucher to draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'PROMO10');
  assert.equal(result.value.voucher.amount, 5000);
});

test('applyVoucher: rejects voucher on issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(invoiceResult.value, []);
  const result = applyVoucher(issued.value, { code: 'PROMO10', amount: 5000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('applyVoucher: rejects second voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let result = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  assert.equal(result.ok, true);

  result = applyVoucher(result.value, { code: 'PROMO20', amount: 10000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'VOUCHER_EXISTS');
});

test('applyVoucher: rejects invalid amount (not integer)', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000.5 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher: rejects zero amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 0 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher: rejects negative amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: -1000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher: does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  assert.deepEqual(invoiceResult.value, original);
});

test('invoiceTotals: includes voucher in totals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const withVoucher = {
    ...invoiceResult.value,
    voucher: { code: 'PROMO10', amount: 10000 },
  };

  const totals = invoiceTotals(withVoucher);
  // DEV-HOUR: 5 × €95.00 = €475.00, VAT 21% = €99.75, Total = €574.75
  // With voucher: €574.75 - €100.00 = €474.75
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.vat, 9975);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 47475);
});

test('invoiceTotals: returns 0 voucher when not applied', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const totals = invoiceTotals(invoiceResult.value);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals: total clamped at 0 with large voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const withVoucher = {
    ...invoiceResult.value,
    voucher: { code: 'PROMO100', amount: 100000 },
  };

  const totals = invoiceTotals(withVoucher);
  assert.equal(totals.voucher, 100000);
  assert.equal(totals.total, 0); // Clamped at 0
});
